import type { Mailable } from '@bespokecore/mail';
import { createTestApp, type TestApp } from '@bespokecore/testing';
import { beforeEach, describe, expect, it } from 'vitest';
import application from '../../bootstrap/app.ts';
import { UserFactory } from './factories/UserFactory.ts';
import { ResetPasswordMail } from './mail/ResetPasswordMail.ts';
import { VerifyEmailMail } from './mail/VerifyEmailMail.ts';
import type { User } from './users.ts';

// Generated by `bespoke make:auth` — the auth module's own tests. They run on SQLite and Postgres.

let app: TestApp;
beforeEach(async () => {
  app = await createTestApp(application, { database: 'refresh' });
});

const credentials = (user: User, password = 'password') => ({ form: { email: user.email, password } });
/** A request that keeps the session of `response`. */
const continuing = (response: { cookie(name: string): string | undefined }) => app.withCookie('bespoke_session', response.cookie('bespoke_session')!);
/** The link in the last mail of a class — path and query. */
const linkIn = <M extends Mailable>(Mail: abstract new (...args: any[]) => M, path: string) => {
  const sent = app.mail.sent(Mail).at(-1)!;
  const url = new URL(new RegExp(`https?://\\S+${path}\\S*(?=\\))`).exec(sent.message.text)![0]);
  return url.pathname + url.search;
};

describe('signing in and out', () => {
  it('signs in with e-mail and password in a new session', async () => {
    const ada = await app.factory(UserFactory).create();
    const planted = await app.get('/login');
    const login = await app.withCookie('bespoke_session', planted.cookie('bespoke_session')!).post('/login', credentials(ada)).assertRedirect('/dashboard').assertAuthenticated(ada);
    expect(login.cookie('bespoke_session')).not.toBe(planted.cookie('bespoke_session')); // session fixation
    await continuing(login).navigating().get('/dashboard').assertPage('auth/Dashboard', { name: ada.name });
  });

  it('answers an unknown e-mail exactly like a wrong password', async () => {
    const ada = await app.factory(UserFactory).create();
    const wrong = await app.post('/login', credentials(ada, 'wrong'));
    const unknown = await app.post('/login', { form: { email: 'nobody@example.com', password: 'wrong' } });
    expect([unknown.status, unknown.session().errors]).toEqual([wrong.status, wrong.session().errors]);
    expect(JSON.stringify(wrong.session())).not.toContain('"wrong"'); // the password is never flashed
  });

  it('throttles failed sign-ins per e-mail and address', async () => {
    const ada = await app.factory(UserFactory).create();
    for (let attempt = 0; attempt < 5; attempt++) await app.post('/login', credentials(ada, 'wrong'));
    await app.post('/login', credentials(ada)).assertInvalid({ email: /^Too many login attempts/ }).assertGuest();
  });

  it('signs out', async () => {
    const ada = await app.factory(UserFactory).create();
    await app.actingAs(ada).post('/logout').assertRedirect('/login').assertGuest();
    await app.expectingJson().get('/dashboard').assertUnauthorized();
  });

  it('leaves nothing for "Back" after signing out: full page load, no-store, Clear-Site-Data', async () => {
    const ada = await app.factory(UserFactory).create();
    await app.actingAs(ada).get('/dashboard').assertOk().assertHeader('cache-control', 'no-store, private');
    // A client-side visit gets 409 + x-bespoke-location: the browser loads the login page fully, the pages it kept in memory are gone.
    const visit = await app.actingAs(ada).navigating().post('/logout').assertStatus(409).assertHeader('x-bespoke-location', '/login').assertGuest();
    expect(visit.headers.get('clear-site-data')).toBe('"cache"');
  });

  it('keeps signing in by the "keep me signed in" cookie', async () => {
    const ada = await app.factory(UserFactory).create();
    const login = await app.post('/login', { form: { ...credentials(ada).form, remember: 'on' } });
    await app.withCookie('remember_web', login.cookie('remember_web')!).get('/dashboard').assertOk().assertAuthenticated(ada);
  });
});

describe('registration and verification', () => {
  const register = (email = 'kj@example.com') =>
    app.post('/register', { form: { name: 'Katherine Johnson', email, password: 'orbital mechanics', password_confirmation: 'orbital mechanics' } });

  it('registers, signs in and mails a signed link that verifies the address', async () => {
    const registered = await register().assertRedirect('/dashboard');
    app.mail.assertSent(VerifyEmailMail, (_mail, message) => message.to[0]!.address === 'kj@example.com');
    const link = linkIn(VerifyEmailMail, '/email/verify/');
    const tampered = link.replace(/\/email\/verify\/\d+\//, '/email/verify/999999/');
    await continuing(registered).expectingJson().get(tampered).assertForbidden();
    await continuing(registered).get(link).assertRedirect('/dashboard').assertSessionHas('status', 'Your e-mail address is verified.');
  });

  it('refuses an address that exists, in any case', async () => {
    await app.factory(UserFactory).create({ email: 'kj@example.com' });
    await register('KJ@example.com').assertInvalid({ email: 'This e-mail address is already registered.' }).assertGuest();
  });
});

describe('password reset', () => {
  it('mails a link that sets a new password once — the same answer for unknown addresses', async () => {
    const ada = await app.factory(UserFactory).create();
    const known = await app.post('/forgot-password', { form: { email: ada.email } });
    const unknown = await app.post('/forgot-password', { form: { email: 'nobody@example.com' } });
    expect(unknown.session().status).toBe(known.session().status);
    app.mail.assertSentCount(ResetPasswordMail, 1);

    const opened = await app.get(linkIn(ResetPasswordMail, '/reset-password')).assertRedirect('/reset-password');
    const cookie = opened.cookie('password_reset')!;
    const reset = () => app.withCookie('password_reset', cookie).post('/reset-password', { form: { password: 'a new password', password_confirmation: 'a new password' } });
    await reset().assertRedirect('/login');
    await reset().assertInvalid({ password: /invalid or has expired/ }); // used up
    await app.post('/login', credentials(ada, 'a new password')).assertAuthenticated(ada);
  });
});

describe('security settings', () => {
  it('ask for the password again ("sudo mode")', async () => {
    const ada = await app.factory(UserFactory).create();
    await app.actingAs(ada).get('/settings/security', { headers: { accept: 'text/html' } }).assertRedirect('/confirm-password');
  });

  it('a new password ends the other sessions', async () => {
    const ada = await app.factory(UserFactory).create();
    const phone = await app.post('/login', credentials(ada));
    const laptop = await app.post('/login', credentials(ada));
    await continuing(laptop).put('/settings/password', { form: { current_password: 'password', password: 'a new password', password_confirmation: 'a new password' } }).assertAuthenticated(ada);
    await continuing(phone).expectingJson().get('/dashboard').assertUnauthorized();
  });
});

describe('API tokens', () => {
  it('creates a token shown once; the API takes it until it is revoked', async () => {
    const ada = await app.factory(UserFactory).create();
    const sudo = continuing(await app.post('/login', credentials(ada)));
    const page = await sudo.navigating().post('/settings/tokens', { json: { name: 'CLI', abilities: ['users:read'] } }).assertOk();
    const plainText = (page.page()!.props as { plainText: string }).plainText;
    const api = (token: string) => app.withHeaders({ authorization: `Bearer ${token}` }).expectingJson();

    await api(plainText).get('/api/user').assertOk().assertExactJson({ id: ada.id, name: ada.name, email: ada.email });
    await api(plainText.slice(0, -1) + (plainText.endsWith('a') ? 'b' : 'a')).get('/api/user').assertUnauthorized(); // checksum
    await app.expectingJson().get('/api/user').assertUnauthorized();
    await sudo.delete(`/settings/tokens/${/^\w*?(\d+)\|/.exec(plainText)![1]}`).assertRedirect('/settings/tokens');
    await api(plainText).get('/api/user').assertUnauthorized();
  });
});

describe('the user type', () => {
  it('carries no password hash', async () => {
    const ada = await app.factory(UserFactory).create();
    expect(ada).not.toHaveProperty('password');
  });
});

// --- Type guarantees (never called) -----------------------------------------------------------

declare const user: User;

export function userTypes() {
  // @ts-expect-error — the hash is not part of a user: it travels separately
  user.password;
}
